// Transcribed from solid-js@1.9.14. `mergeProps` and `createSignal` are the
// signatures this fixture's proof depends on and are byte-faithful to
// `types/render/component.d.ts:93` and `types/reactive/signal.d.ts:138-139`;
// the `MergeProps`/`Simplify` result mapping is reduced to `unknown` because
// nothing here reads the merged result, and a *looser return* cannot create a
// callback row. Nothing on the argument side is loosened: `mergeProps` accepts
// any tuple, exactly as published, so a props object at a merge source is as
// admissible here as it is in a real project.
export type Accessor<T> = () => T;
export type Signal<T> = [Accessor<T>, (next: T) => T];
export interface SignalOptions<T> {
  name?: string;
  equals?: false | ((previous: T, next: T) => boolean);
}

export declare function createMemo<T>(fn: () => T): Accessor<T>;
export declare function createSignal<T>(): Signal<T | undefined>;
export declare function createSignal<T>(value: T, options?: SignalOptions<T>): Signal<T>;
export declare function mergeProps<T extends unknown[]>(...sources: T): unknown;
